package com.menter.treatmentvault.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.menter.treatmentvault.*;import com.menter.treatmentvault.data.*;import kotlinx.coroutines.launch
@Composable fun ExamScreen(back:()->Unit){val dao=(androidx.compose.ui.platform.LocalContext.current.applicationContext as TreatmentVaultApplication).database.dao();val list by dao.exams().collectAsState(emptyList());val scope=rememberCoroutineScope();var add by remember{mutableStateOf(false)};Page("检查报告",back){LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(list){v->Card{Column(Modifier.padding(12.dp)){Text(v.name,style=MaterialTheme.typography.titleMedium);Text("${v.date} · ${v.type} · ${v.hospital}");if(v.summary.isNotBlank())Text(v.summary)}}}};Button({add=true},Modifier.fillMaxWidth()){Text("新增检查")}}
if(add){var name by remember{mutableStateOf("")};var date by remember{mutableStateOf("")};var type by remember{mutableStateOf("其他")};var summary by remember{mutableStateOf("")};AlertDialog({add=false},{TextButton({if(name.isNotBlank())scope.launch{dao.saveExam(ExamEntity(name=name,date=date,type=type,summary=summary));add=false}}){Text("保存")}},dismissButton={TextButton({add=false}){Text("取消")}},title={Text("新增检查")},text={Column{Field(name,{name=it},"检查名称");Field(date,{date=it},"日期 YYYY-MM-DD");Field(type,{type=it},"类型");Field(summary,{summary=it},"结果摘要")}})} }
